const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  const normalized = text(value).toLowerCase();
  return ['true', '1', 'yes', 'on'].includes(normalized);
};

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const appointment_id = Number(input.appointment_id);
const new_target_date = text(input.new_target_date);
const new_start_time = text(input.new_start_time);
const reschedule_reason = text(input.reschedule_reason);
const confirm_reschedule = toBoolean(input.confirm_reschedule);

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل باید فقط شامل اعداد و در صورت نیاز علامت + باشد.',
  });
}

if (!Number.isInteger(appointment_id) || appointment_id < 1) {
  errors.push({
    field: 'appointment_id',
    message: 'appointment_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

function isRealIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const [year, month, day] = value.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  return (
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day
  );
}

if (!new_target_date || !isRealIsoDate(new_target_date)) {
  errors.push({
    field: 'new_target_date',
    message: 'تاریخ جدید باید معتبر و با قالب YYYY-MM-DD باشد.',
  });
}

if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(new_start_time)) {
  errors.push({
    field: 'new_start_time',
    message: 'ساعت جدید باید با قالب HH:MM باشد.',
  });
}

if (!reschedule_reason) {
  errors.push({
    field: 'reschedule_reason',
    message: 'علت جابه‌جایی نوبت الزامی است.',
  });
}

if (reschedule_reason.length > 500) {
  errors.push({
    field: 'reschedule_reason',
    message: 'علت جابه‌جایی نباید بیشتر از 500 کاراکتر باشد.',
  });
}

if (confirm_reschedule !== true) {
  errors.push({
    field: 'confirm_reschedule',
    message: 'جابه‌جایی نوبت باید ابتدا توسط بیمار تأیید شود.',
  });
}

return [
  {
    json: {
      clinic_name,
      mobile,
      appointment_id,
      new_target_date,
      new_start_time,
      reschedule_reason,
      confirm_reschedule,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

