const db = $('Reschedule Appointment in Database').first().json;

return [
  {
    json: {
      ...db,
      success: true,
      result: 'rescheduled',
      message: 'نوبت با موفقیت جابه‌جا و تقویم به‌روزرسانی شد.',
      calendar_sync_status: 'recreated',
      google_calendar_event_id: $json.google_calendar_event_id,
    },
  },
];

const db = $('Reschedule Appointment in Database').first().json;

return [
  {
    json: {
      ...db,
      success: true,
      result: 'rescheduled',
      message: 'نوبت در دیتابیس جابه‌جا شد، اما ساخت رویداد جدید Google Calendar ناموفق بود.',
      calendar_sync_status: 'create_failed',
      google_calendar_event_id: null,
    },
  },
];

if (
  $json.result === 'reschedule_conflict' &&
  $json.success === false
) {
  return [{ json: $json }];
}

const message =
  $json.error?.message ??
  $json.errorMessage ??
  $json.message ??
  'خطای دیتابیس هنگام جابه‌جایی نوبت رخ داد.';

if (String(message).includes('appointment_time_blocked_by_schedule_exception')) {
  return [
    {
      json: {
        success: false,
        result: 'target_time_blocked',
        message: 'زمان جدید در برنامه پزشک مسدود شده است.',
      },
    },
  ];
}

return [
  {
    json: {
      success: false,
      result: 'database_reschedule_error',
      message,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      errors: $json.errors ?? [],
    },
  },
];

return [
  {
    json: {
      success: false,
      result: $json.result,
      message: $json.message,
      appointment_id: $json.appointment_id ?? null,
      patient_name: $json.patient_name ?? null,
      doctor_name: $json.doctor_name ?? null,
      service_name: $json.service_name ?? null,
      old_appointment_start: $json.old_appointment_start ?? null,
      new_appointment_start: $json.new_appointment_start ?? null,
    },
  },
];
